/*
  настройки.js — ЧИСЛА И АДРЕСА. Всё, что настраивается, но не читается
  человеком на экране.

  Чем отличается от соседей: в мир.js лежит содержание (тексты, народы),
  здесь — параметры (сколько знаков в имени, какой размер портрета,
  сколько ждать сервис). В герой.js не должно быть ни того, ни другого.
*/

window.СБОРКА_НАСТРОЙКИ = {

  /* ── ХРАНЕНИЕ ────────────────────────────────────────────────────── */
  хранение: {
    ключ: 'вэрн.герой.1',   // один ключ, внутри вся запись вместе с портретом
    версияЗаписи: 4,        // растёт при смене устройства записи — см. ТЗ 3

    /*  Метка этого браузера. Не опознание человека: случайное число,
        нужное посреднику, чтобы считать портреты по устройствам.
        Стирается вместе с памятью браузера — так и задумано.       */
    ключУстройства: 'вэрн.устройство'
  },

  /*  ЧТО СЧИТАЕТСЯ ГОДНОЙ ЗАПИСЬЮ ПРИ ЧТЕНИИ.

      Проверки при вводе мало: ввода могло не быть вовсе. Запись лежит
      в памяти браузера, которую человек правит руками, и приходит от
      друга кодом переноса героя. Оба места — чужие данные.        */
  запись: {
    цвет: /^#[0-9a-fA-F]{3,8}$/,
    картинка: /^data:image\//,

    // какие поля записи чем обязаны быть
    цветныеПоля: ['цветПлаща', 'цветКожи', 'цветВолос'],
    картинки:    ['портрет']
  },

  /* ── ИМЯ ─────────────────────────────────────────────────────────── */
  имя: {
    мин: 2,
    макс: 20,
    // допустимые знаки: буквы двух алфавитов, пробел, дефис
    разрешённыеЗнаки: '[^А-Яа-яЁёA-Za-z \\-]',
    цифры: '[0-9]',
    дваПробела: ' {2}'
  },

  /* ── КОНСТРУКТОР ─────────────────────────────────────────────────── */
  шагов: 4,                 // народ · облик · имя · подтверждение

  /* ── ПОРТРЕТ ─────────────────────────────────────────────────────
     Страница НЕ ходит к генератору сама. Между ними стоит посредник:
     `готово/посредник/`. Причины — в `docs/тз-посредник.md`, коротко:
     лицензия старой модели запрещала коммерцию, лимиты считались на
     всех наших людей разом, а платный ключ в браузере уводят за день.

     Здесь нет и не должно быть ни ключа, ни имени модели, ни адреса
     поставщика. Поставщик меняется одной строкой В ПОСРЕДНИКЕ, эта
     папка при этом не трогается вовсе.                             */
  портрет: {

    /*  АДРЕС ПОСРЕДНИКА.
        Пусто — посредника ещё нет. Тогда портрет просто не рисуется,
        а герой всё равно создаётся и входит в мир. Это не запасной
        путь, а требование: мир открывается без портрета.

        Появится выложенный посредник — сюда вписывается его адрес,
        одной строкой, и больше нигде ничего.                       */
    адрес: '',
    дело: 'портрет',

    /*  ИСТОЧНИК КАРТИНОК — ОДНА СТРОКА, И БОЛЬШЕ НИГДЕ НИЧЕГО.

        'посредник'    — наш воркер на Cloudflare, FLUX.1 schnell.
                         Цель. Требует выложенного посредника выше.
        'pollinations' — времянка, пока посредника нет. Ключа не
                         просит, счёт по людям не ведёт.

        Смена этой строки метит все прежние портреты старыми: их лица
        рисовала другая модель, и при первом же входе они молча
        пересоздаются. Так переезд на FLUX обойдётся без разговоров с
        человеком и без потери героев.                              */
    источник: 'pollinations',

    /*  Времянка. Замерено 31 августа: одна картинка в 45 секунд на
        адрес сети, уже сделанная отдаётся из их памяти за 0.2 с.
        Зерно действует — два зерна дают разные лица, проверено
        отпечатками байт.                                           */
    времянка: {
      адрес: 'https://image.pollinations.ai/prompt/'
    },

    /*  Кадр под фигуру в полный рост, а не под лицо. При квадрате
        герой занимал бы едва треть высоты, и на карте в 64 единицы от
        него осталось бы пятно.                                      */
    ширина: 512,
    высота: 768,

    /*  ── БИБЛИОТЕКА ЛИЦ ──────────────────────────────────────────
        Лицо человек получает МГНОВЕННО, из готовых картинок. Живая
        генерация осталась только под кнопкой «нарисовать моё лицо».

        Имя файла собрано из КЛЮЧЕЙ ВЫБОРА, а не из номера: ключи уже
        лежат в записи героя, поэтому картинка находится по имени и
        никакого списка соответствий не нужно.

        Библиотека собрана не вся: сейчас в ней оба пола, четыре
        народа и четыре цвета кожи при телосложении «обычный» и
        отметине «нет». Кого в ней нет — тот ходит фигуркой,
        нарисованной кодом. Так было до библиотеки, так и осталось.

        В первую загрузку библиотека НЕ входит: человеку уходит одна
        картинка по имени файла.

        Порядок ключей менять нельзя — по нему названы все файлы.  */
    библиотека: {
      фигуры: 'библиотека/фигуры/',
      вид: '.webp',
      ключи: ['пол', 'народ', 'цвет', 'телосложение', 'отметина'],

      /*  ЧЕМ ЗАМЕНИТЬ, ПОКА БИБЛИОТЕКА НЕПОЛНА.

          Точного файла может не быть: библиотека собирается часами.
          Тогда берём ближайшего — тот же пол, народ и цвет кожи, но
          обычного сложения и без отметины. Со шрамом не совпадёт,
          зато в мире стоит почти он, а не общая фигурка.

          Когда библиотека полна, эта замена не понадобится ни разу:
          точный путь найдётся всегда.                             */
      ближний: { телосложение: 'обычный', отметина: 'нет' }
    },

    /*  ЧТО ЛОЖИТСЯ В ЗАПИСЬ.

        Пришедшая картинка НЕ сохраняется как есть. В JPEG от времянки
        лежит Exif с нашим запросом открытым текстом — а портрет потом
        расходится по людям. Перерисовка на холсте оставляет одни
        точки: Exif не переносится. Заодно падает вес.

        МЕДАЛЬОН — не уменьшенный портрет, а ОБРЕЗКА ПО ГОЛОВЕ.
        Проверено на шести героях: в 26 точках целый портрет
        превращается в пятно, лицо занимает 8 точек из 26. Берём
        квадрат в 60% высоты по середине ширины, от верхнего края —
        тогда лицо читается у всех, включая сажево-чёрного Гарнаха.
        На 50% срезается макушка, на 70% лицо снова мельчает.      */
    /*  ЧТО ЛОЖИТСЯ В ЗАПИСЬ.

        Одна картинка на героя — фигура во весь рост с вырезанным
        фоном. Медальон отменён вместе с рисованной фигуркой: он был
        нужен, только пока фигуру нельзя было вырезать из фона.

        Пришедшее не сохраняется как есть: в JPEG от времянки лежит
        Exif с нашим запросом открытым текстом, а картинка расходится
        по людям. Перерисовка на холсте оставляет одни точки.        */
    картинка: {
      вид: 'image/webp',
      фигура: { ширина: 256, высота: 384, качество: 0.82 }
    },


    /*  Коды бед. Приходят от посредника, надписи к ним — в `мир.js`
        под ключом «приставка + код». Служебные слова, человеку их
        никто не покажет.                                          */
    /*  Чистка имени из свободного описания. Точного совпадения мало:
        по-русски имя склоняется — «Кром» уходит наружу как «Крома».
        Поэтому режем и слова, начинающиеся с имени и добавившие
        короткое окончание. Коротким именам приставку не применяем,
        иначе «Ор» съест «орех».                                   */
    чисткаИмени: {
      наименьшаяОснова:    4,
      наибольшееОкончание: 3
    },

    коды: {
      приставка:     'беда_',
      нетПосредника: 'нет_посредника',
      отказ:         'отказ_поставщика'
    },

    /*  Порог ОТКАЗА, а не ожидания на экране: человек уходит в мир
        сразу, портрет догоняет. Шестьдесят, потому что времянка
        отвечает за 38–45 секунд, и при двадцати не успевал никто. */
    ожиданиеМс: 60000,

    /*  ЗАПРОС СОБИРАЕТСЯ СТРОГО В ЭТОМ ПОРЯДКЕ:
          каркас → народ и облик → свободное описание → хвост
        Порядок менять нельзя: хвост должен идти последним, иначе
        свободный текст может его перебить.                          */

    /*  КАРКАС — жёсткая строка стиля, одна и та же для всех героев.

        ВО ВЕСЬ РОСТ, а не по грудь. По карте ходит сам герой, а не
        фигурка, нарисованная кодом: фон вырезается нейросетью, и
        рисованный заменитель с медальоном над ним больше не нужен.

        СТОИТ В КОНЦЕ ЗАПРОСА, а не в начале. Первая проба каркаса шла
        первой строкой и была 66 слов — модель до примет героя не
        дочитывала: шесть разных народов вышли одним лицом.

        Одежда названа прямо: без неё модель раздевает героев, а у нас
        наименьший возраст 16 и чужие люди в мире. Вырез не
        описывается вовсе — описанное модель рисует.

        Запретное сюда НЕ входит: оно уходит отдельным полем, потому
        что модель читает не «no nudity», а «nudity».                */
    /*  КАРКАС — рамка кадра и манера письма. Идёт ПОСЛЕДНИМ.

        Это проверенное сочетание, и я его однажды сломал сам: вынес
        рамку вперёд, и Гарнах вышел целиком, но без топора, без
        клыков и без манеры письма. Что ставишь вперёд — то и
        получаешь, остальное теряется. Не переставлять.

        Слово `figure` здесь нужно: без него камера подъезжает к
        поясу. Оно же тянет статуэтку на постаменте, и запретным полем
        она не убирается — проверено. Убирается только землёй,
        названной прямо: голая земля, ступни прямо на почве.

        РОВНОГО ФОНА БОЛЬШЕ НЕ ПРОСИМ, и это не мелочь. Он остался от
        поры, когда фон вырезали по цвету; сейчас его режет rembg — по
        содержимому, а не по оттенку. А «ровный тёмный фон» для модели
        значит студийную съёмку, и оттуда же берётся постамент под
        ногами: она рисует не человека, а статуэтку на подставке.
        Открытое поле снимает и то и другое.

        ЗАПАС СВЕРХУ И СНИЗУ ПРОСИТСЯ ПРЯМО: ступни срезались по
        нижнему краю. Лишнее поле уходит само при вырезании фона —
        `собрать-лица.py` обрезает по краям непрозрачного. Дорисовать
        ступни мы не умеем, обрезать лишнее умеем.                  */
    каркас: 'full length view of the entire figure from head to boots, ' +
            'standing upright on flat bare earth, feet directly on the soil, ' +
            'both feet visible, ' +
            'empty space above the head and below the feet, ' +
            'facing the viewer, small figure far from the camera, ' +
            'oil painting, visible brush strokes, ' +
            'one soft light from the upper left, ' +
            'standing outdoors in an open field',

    /*  Сколько раз можно получить портрет на одного героя.

        Считаются только УДАЧНЫЕ получения. Пустые попытки, когда
        посредник молчит, не тратятся — иначе человек остался бы без
        портрета навсегда, ничего не нарушив.                       */
    попытокПредел: 3
  },

  /* ── СВОБОДНОЕ ОПИСАНИЕ ГЕРОЯ ─────────────────────────────────────
     Человек пишет своими словами поверх выбранного народа и облика. */
  описание: {
    макс: 200
  },

  зерно: { предел: 1000000 },   // случайное целое, хранится вместе с героем

  /* ── ЗНАК НАРОДА ──────────────────────────────────────────────────
     Рисуется кодом, размер берётся от места, в котором стоит.       */
  знак: {
    доля: 0.5,               // какую часть своего места занимает
    поУмолчанию: 26,         // пока место ещё не измерено браузером
    холст: '0 0 24 24',      // система координат путей из мир.js
    толщинаЛинии: 1.5,
    // нужно, чтобы знак рисовался ещё и на карточке: там он идёт
    // картинкой, а без пространства имён svg картинкой не считается
    пространствоИмён: 'http://www.w3.org/2000/svg'
  },

  /* ── КАРТОЧКА ДЛЯ ОТПРАВКИ ДРУЗЬЯМ ───────────────────────────────── */
  карточка: {
    ширина: 1080,
    высота: 1350,
    имяФайла: 'герой-вэрн.png',
    качество: 0.92,
    /* доли от ширины карточки — чтобы всё считалось от одного числа */
    поле: 0.075,
    /* Раскладка карточки считается сверху вниз и должна уложиться до
       нижней строки. При портрете крупнее 0.66 строка судьбы из трёх
       строк наезжает на подпись мира — проверено. */
    портретДоля: 0.66,
    знакДоля: 0.070,
    кегльИмени: 0.085,
    жирностьИмени: 500,
    кегльНарода: 0.032,
    кегльСудьбы: 0.030,
    кегльПодписи: 0.022,
    /* отступы сверху вниз, тоже долями от ширины */
    отступПослеПортрета: 0.055,
    отступПослеЗнака: 0.075,
    отступПослеИмени: 0.048,
    отступПослеНарода: 0.052,
    межстрочный: 1.45,
    толщинаРамки: 0.003,
    шрифт: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
    /* Карточка уходит в чат и там живёт сама по себе: тема мессенджера
       на неё не действует. Поэтому цвета здесь свои и постоянные. */
    цвета: {
      фон: '#0f1319',
      текст: '#e8f4f8',
      тусклый: '#8794a0',
      рамка: '#2a3038'
    }
  },

  /* ── ОФОРМЛЕНИЕ ВНЕ ТЕЛЕГРАМА ────────────────────────────────────────
     В Телеграме цвета берутся из темы мессенджера. Эти значения
     подставляются только когда приложение открыто обычным браузером. */
  запаснаяТема: {
    bg_color: '#0b0f14',
    secondary_bg_color: '#12161c',
    text_color: '#e8f4f8',
    hint_color: '#7a8894',
    link_color: '#2dd4bf',
    button_color: '#2dd4bf',
    button_text_color: '#0b0f14',
    destructive_text_color: '#e2725b'
  }
};
